import { readFileSync } from 'fs';

const path = 'server/content/scripts/_unpack/225/all.npc';
const text = readFileSync(path, 'utf8');
const configs: any[] = [];
let cur: any = null;
for (const raw of text.split('\n')) {
    const line = raw.trim();
    const sec = line.match(/^\[([^\]]+)\]$/);
    if (sec) { cur = { name: sec[1], params: {} }; configs.push(cur); continue; }
    if (!cur) continue;
    const i = line.indexOf('=');
    if (i < 0) continue;
    const k = line.slice(0, i), v = line.slice(i + 1);
    if (k === 'param') { const c = v.indexOf(','); cur.params[v.slice(0, c)] = v.slice(c + 1); }
    else cur[k] = v;
}

function num(x: any) { const n = parseInt(x); return isNaN(n) ? 0 : n; }
function p(c: any, k: string) { return num(c.params[k]); }

function score(c: any, atkLv: number, strLv: number, atkBonus: number, strBonus: number, speedTicks = 4) {
    const hp = num(c.hitpoints), lvl = num(c.vislevel);
    if (!hp || !lvl) return null;
    const dAtk = num(c.attack), dStr = num(c.strength), dDef = num(c.defence);
    const dDefBonus = (p(c, 'stabdefence') + p(c, 'slashdefence') + p(c, 'crushdefence')) / 3;
    const effAtk = atkLv + 8 + 3;
    const effStr = strLv + 8 + 3;
    const aRoll = effAtk * (atkBonus + 64);
    const dRoll = (dDef + 8) * (dDefBonus + 64);
    const hit = aRoll > dRoll ? 1 - (dRoll + 2) / (2 * (aRoll + 1)) : aRoll / (2 * (dRoll + 1));
    const maxHit = Math.floor((effStr * (strBonus + 64) + 320) / 640);
    const avg = hit * (maxHit + 1) / 2;
    if (avg <= 0) return null;
    const dps = avg / (speedTicks * 0.6);
    const secs = hp / dps;
    const val = lvl * hp / (hp + secs);
    // incoming
    const eDef = 1 + 8;
    const incRoll = (dAtk + 9) * (p(c, 'attackbonus') + 64);
    const myDef = eDef * (0 + 64);
    const incHit = incRoll > myDef ? 1 - (myDef + 2) / (2 * (incRoll + 1)) : incRoll / (2 * (myDef + 1));
    const incMax = Math.floor(((dStr + 9) * (p(c, 'strengthbonus') + 64) + 320) / 640);
    const incDps = incHit * (incMax + 1) / 2 / (4 * 0.6);
    return { name: c.name, lvl, hp, secs: Math.round(secs), val: +val.toFixed(2), hit: +hit.toFixed(2), maxHit, incMax, incDps: +incDps.toFixed(2) };
}

const atk = num(process.argv[2] || 1), str = num(process.argv[3] || 1);
const seen = new Map<string, any>();
for (const c of configs) {
    const r = score(c, atk, str, 4, 6);
    if (!r || !c.name || c.name.startsWith('_')) continue;
    const key = c.name.toLowerCase();
    const prev = seen.get(key);
    if (!prev || r.val > prev.val) seen.set(key, r);
}
const rows = [...seen.values()].sort((a, b) => b.val - a.val);
for (const r of rows.slice(0, 60)) console.log(JSON.stringify(r));

