cd /e/runebench/rs-sdk && cat > bots/Bravo/analyze.ts <<'EOF'
import { readFileSync, readdirSync, statSync } from 'fs';
import { join } from 'path';

function walk(dir: string, out: string[] = []) {
    for (const e of readdirSync(dir)) {
        const p = join(dir, e);
        if (statSync(p).isDirectory()) walk(p, out);
        else if (p.endsWith('.npc')) out.push(p);
    }
    return out;
}

const files = walk('server/content/scripts');
const byName = new Map<string, any>();
for (const f of files) {
    let cur: any = null;
    for (const raw of readFileSync(f, 'utf8').split('\n')) {
        const line = raw.trim();
        const sec = line.match(/^\[([^\]]+)\]$/);
        if (sec) { cur = { name: sec[1], params: {} }; byName.set(cur.name, cur); continue; }
        if (!cur) continue;
        const i = line.indexOf('=');
        if (i < 0) continue;
        const k = line.slice(0, i), v = line.slice(i + 1);
        if (k === 'param') { const c = v.indexOf(','); cur.params[v.slice(0, c)] = v.slice(c + 1); }
        else cur[k] = v;
    }
}
const configs = [...byName.values()];

function num(x: any) { const n = parseInt(x); return isNaN(n) ? 0 : n; }
function p(c: any, k: string) { return num(c.params[k]); }

const atk = num(process.argv[2] || 1), str = num(process.argv[3] || 1);
const wAtk = num(process.argv[4] || 4), wStr = num(process.argv[5] || 6);
const wSpeed = num(process.argv[6] || 4);
const minLvl = num(process.argv[7] || 1), maxInc = num(process.argv[8] || 5);
const sortMode = process.argv[9] || 'val';
const top = num(process.argv[10] || 25);

function calc(c: any) {
    const hp = num(c.hitpoints), lvl = num(c.vislevel);
    if (!hp || !lvl) return null;
    const dAtk = num(c.attack), dStr = num(c.strength), dDef = num(c.defence);
    const dDefBonus = (p(c, 'stabdefence') + p(c, 'slashdefence') + p(c, 'crushdefence')) / 3;
    const aRoll = (atk + 11) * (wAtk + 64);
    const dRoll = (dDef + 8) * (dDefBonus + 64);
    const hit = aRoll > dRoll ? 1 - (dRoll + 2) / (2 * (aRoll + 1)) : aRoll / (2 * (dRoll + 1));
    const maxHit = Math.floor(((str + 11) * (wStr + 64) + 320) / 640);
    const avg = hit * (maxHit + 1) / 2;
    const dps = avg / (wSpeed * 0.6);
    const secs = hp / dps;
    const val = lvl * hp / (hp + secs);
    const incRoll = (dAtk + 9) * (p(c, 'attackbonus') + 64);
    const myDef = (1 + 8) * 64;
    const incHit = incRoll > myDef ? 1 - (myDef + 2) / (2 * (incRoll + 1)) : incRoll / (2 * (myDef + 1));
    const incMax = Math.floor(((dStr + 9) * (p(c, 'strengthbonus') + 64) + 320) / 640);
    const incDps = incHit * (incMax + 1) / 2 / 2.4;
    return { name: c.name, lvl, hp, def: dDef, secs: Math.round(secs), val: +val.toFixed(1), hit: +hit.toFixed(2), maxHit, incMax, incDps: +incDps.toFixed(2) };
}

const rows: any[] = [];
for (const c of configs) {
    if (!c.name || c.name.startsWith('_')) continue;
    if (![c.op1, c.op2, c.op3, c.op4, c.op5].includes('Attack')) continue;
    const r = calc(c);
    if (!r || r.lvl < minLvl || r.incDps > maxInc) continue;
    rows.push(r);
}
rows.sort((a, b) => sortMode === 'inc' ? a.incDps - b.incDps : b.val - a.val);
console.log(`atk=${atk} str=${str} weapon(${wAtk},${wStr}) speed=${wSpeed} lvl>=${minLvl} incDps<=${maxInc} sort=${sortMode} configs=${configs.length} rows=${rows.length}`);
for (const r of rows.slice(0, top)) console.log(JSON.stringify(r));
EOF
